import { Axios, isAxiosError } from 'axios';
import { HttpClientError } from './HttpClientError';

export function addErrorHandlingInterceptor(client: Axios) {
  client.interceptors.response.use(
    (response) => response, // Pass through successful responses
    (error) => {
      if (!isAxiosError(error) || !error.response || !error.config || !error.config.url || !error.config.method) {
        throw error;
      }
      // Build a cleaner error structure than Axios provides
      throw new HttpClientError(
        error.response.status,
        error.config.url,
        error.config.method,
        error.response.data,
        error.message,
      );
    },
  );
}
